package vn.edu.webpro.robotlab.dao;
import java.sql.*;import java.util.*;import vn.edu.webpro.robotlab.model.LibraryResource;
public final class LibraryResourceDao{private final DatabaseConnectionFactory connections;public LibraryResourceDao(DatabaseConnectionFactory connections){this.connections=connections;}public List<LibraryResource> list(int limit,int offset,String robotId)throws SQLException{String sql="SELECT id,robot_id,title,type,url,description FROM library_resources"+(robotId==null?"":" WHERE robot_id=?")+" ORDER BY id LIMIT ? OFFSET ?";List<LibraryResource> data=new ArrayList<>();try(Connection c=connections.openConnection();PreparedStatement s=c.prepareStatement(sql)){int p=1;if(robotId!=null)s.setString(p++,robotId);s.setInt(p++,limit);s.setInt(p,offset);try(ResultSet r=s.executeQuery()){while(r.next())data.add(new LibraryResource(r.getString("id"),r.getString("robot_id"),r.getString("title"),r.getString("type"),r.getString("url"),r.getString("description")));}}return data;}public long count(String robotId)throws SQLException{try(Connection c=connections.openConnection();PreparedStatement s=c.prepareStatement("SELECT COUNT(*) FROM library_resources"+(robotId==null?"":" WHERE robot_id=?"))){if(robotId!=null)s.setString(1,robotId);try(ResultSet r=s.executeQuery()){r.next();return r.getLong(1);}}}}
